(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.28)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.4)*8 + Math.cos((x-y)*0.012-t*0.35)*6;
  const w2y = Math.cos((x-y)*0.011-t*0.38)*8 + Math.sin((x+y)*0.009+t*0.42)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 120+Math.cos(t*0.65+2)*70, 0.07, 2.1, 1.0],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.1, 1.6, 0.88]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const att = 1/(1+d*0.004);
    aS += Math.sin(d*f - t*sp) * att * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * att * w;
    wS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * att * w * 0.5;
  }
  const act = aS/8, inh = iS/8, wav = wS/8;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*1.0);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.3;
  const bg4 = Math.sin((sx-sy)*0.09-t*1.8)*0.3;
  const bg5 = Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.2;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const turb = Math.sin(sx*0.08+t*0.9)*Math.cos(sy*0.07-t*0.7)*0.15;
  const feed = act*0.55 - inh*0.45 + bg*0.25 + spiral*0.2 + wav*0.15 + turb;
  const lap = Math.tanh(feed*2.5);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.09+t)*0.4 + Math.sin(sx*0.07-t*0.8)*Math.cos(sy*0.11+t*0.6)*0.3)*1.8)*0.25;
  const reaction = Math.tanh((lap*0.7 + cell*0.3)*1.8);
  const glow = Math.exp(-Math.abs(reaction)*0.8)*0.3;
  const blend = reaction + glow;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,48],[12,42,82],[18,78,112],[28,125,128],
    [55,165,125],[140,195,90],[210,195,65],[230,145,55],
    [215,90,65],[185,55,75],[120,35,72],[65,22,60],[6,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const smooth = f*f*(3-2*f);
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65 ? 1.12 : 1.0;
  const highlight = glow > 0.15 ? 1.08 : 1.0;
  const m = lum*edge*highlight;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth)*m)|0
  ];
}
